public class CharFrequencyCounter {

    public static void main(String[] args) {
        // *highlighted section 1*: input string initialization
        String input = "Hello, World!";

        // *highlighted section 2*: convert input string to char array
        char[] charArray = input.toCharArray();

        // *highlighted section 3*: initialize HashMap to store frequency counts
        Map<Character, Integer> frequencyMap = new HashMap<>();

        // *highlighted section 4*: iterate through char array
        for (char c : charArray) {
            // *highlighted section 5*: check for supported characters (letters, digits, space, and common punctuations)
            if (isSupportedCharacter(c)) {
                // *highlighted section 6*: update frequency count in the map
                frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
            } else {
                // *highlighted section 7*: handle unsupported characters gracefully
                System.err.println("Warning: Unsupported character detected and skipped: '" + c + "'");
            }
        }

        // *highlighted section 8*: print the frequency map result
        System.out.println("Character frequencies in the input string:");
        for (Map.Entry<Character, Integer> entry : frequencyMap.entrySet()) {
            System.out.println("'" + entry.getKey() + "' : " + entry.getValue());
        }
    }

    private static boolean isSupportedCharacter(char c) {
        // Letters (a-z, A-Z), digits (0-9), whitespace, and basic punctuations considered supported
        return Character.isLetterOrDigit(c) || Character.isWhitespace(c) || isBasicPunctuation(c);
    }

    private static boolean isBasicPunctuation(char c) {
        // Common punctuation characters supported
        char[] supportedPunctuations = {',', '.', '!', '?', ';', ':', '\'', '\"', '-'};
        for (char p : supportedPunctuations) {
            if (c == p) {
                return true;
            }
        }
        return false;
    }
}
