        self.lowercase = set()
        self.digits = set()
        self.symbols = set()
        self.total_count = 0
        self.strings = []

    def add_string(self, text):
        self.strings.append(text)
        for char in text:
            self.total_count += 1
            if char.isupper():
                self.uppercase.add(char)
            elif char.islower():
                self.lowercase.add(char)
            elif char.isdigit():
                self.digits.add(char)
            else:
                self.symbols.add(char)

    def union(self, category1, category2):
        set1 = getattr(self, category1, set())
        set2 = getattr(self, category2, set())
        return set1.union(set2)

    def intersection(self, category1, category2):
        set1 = getattr(self, category1, set())
        set2 = getattr(self, category2, set())
        return set1.intersection(set2)

    def difference(self, category1, category2):
        set1 = getattr(self, category1, set())
        set2 = getattr(self, category2, set())
        return set1.difference(set2)

    def summary(self):
        summary_data = {
            'uppercase_count': len(self.uppercase),
            'lowercase_count': len(self.lowercase),
            'digits_count': len(self.digits),
            'symbols_count': len(self.symbols),
