def matrix_power(matrix, n, power):
    result = [[0 for x in range(n)] for y in range(n)]
    temp = [[0 for x in range(n)] for y in range(n)]
    # Initialize result as identity matrix
    for i in range(n):
        for j in range(n):
            if i == j:
                result[i][j] = 1
            else:
                result[i][j] = 0
    # Copy of matrix to work on
    for i in range(n):
        for j in range(n):
            temp[i][j] = matrix[i][j]

    p = power
    while p > 0:
        if p % 2 == 1:
            result = multiply_matrices(result, temp, n)
        temp = multiply_matrices(temp, temp, n)
        p //= 2

    return result

def multiply_matrices(a, b, n):
    res = [[0 for x in range(n)] for y in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                res[i][j] += a[i][k] * b[k][j]
    return res

